"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def FindIntersection(arr1, arr2):
    i = 0
    j = 0
    intersection = []
    while ((i < len(arr1)) and (j < len(arr2))):
        if (arr1[i] == arr2[j]):
            if ((len(intersection) == 0) or (intersection[(-1)] != arr1[i])):
                intersection.append(arr1[i])
            i = (i + 1)
            j = (j + 1)
        elif (arr1[i] < arr2[j]):
            i = (i + 1)
        else:
            j = (j + 1)
    return intersection

print(FindIntersection([1, 2, 3, 4, 5], [0, 2, 4, 6, 8]))